  "plural_rules" => {
    "cardinal_rule_1" => {
      "expression" => "(n) == 1 ? \"one\" : \"other\"",
      "forms" => [
        "one",
        "other"
      ]
    },
    "cardinal_rule_2" => {
      "expression" => "(n) == 1 ? \"one\" : (n) && (n) % 1000000 == 0 ? \"many\" : \"other\"",
      "forms" => [
        "many",
        "one",
        "other"
      ]
    },
    "cardinal_rule_3" => {
      "expression" => "(n) <= 1 ? \"one\" : (n) % 1000000 == 0 ? \"many\" : \"other\"",
      "forms" => [
        "many",
        "one",
        "other"
      ]
    },
    "cardinal_rule_4" => {
      "expression" => "(n) % 10 == 1 && (n) % 100 != 11 ? \"one\" : \"other\"",
      "forms" => [
        "one",
        "other"
      ]
    },
    "cardinal_rule_5" => {
      "expression" => "(n) % 10 == 1 && (n) % 100 != 11 ? \"one\" : (n) % 10 >= 2 && (n) % 10 <= 4 && ((n) % 100 < 12 || (n) % 100 > 14) ? \"few\" : \"many\"",
      "forms" => [
