    },
    "cardinal_rule_6" => {
      "expression" => "(n) == 0 ? \"zero\" : (n) == 1 ? \"one\" : (n) == 2 ? \"two\" : (n) == 3 ? \"few\" : (n) == 6 ? \"many\" : \"other\"",
      "forms" => [
        "zero",
