    },
    "cardinal_rule_7" => {
      "expression" => "n == 0 ? \"zero\" : n == 1 ? \"one\" : n == 2 ? \"two\" : n % 100 >= 3 && n % 100 <= 10 ? \"few\" : n % 100 >= 11 && n % 100 <= 99 ? \"many\" : \"other\"",
      "forms" => [
        "zero",
        "one",
        "two",
        "few",
        "many",
        "other"
      ]
    },
    "cardinal_rule_8" => {
      "expression" => "(n) == 1 ? \"one\" : (n) == 2 ? \"two\" : \"other\"",
      "forms" => [
        "one",
        "two",
        "other"
      ]
    },
    "cardinal_rule_9" => {
      "expression" => "(n) <= 1 ? \"one\" : \"other\"",
      "forms" => [
